export const UploadStatus = Schema.Struct({ "chunkSize": Bytes, "fileId": Schema.Union(Id, Schema.Null), "parts": Schema.Array(AcknowledgedPart), "state": UploadState, "totalParts": Bytes, "uploadId": Id });

export type UploadStatus = typeof UploadStatus.Type;

export const UsersInput = Schema.Struct({ "cursor": Schema.optional(Schema.Union(Schema.String, Schema.Null)) });

export type UsersInput = typeof UsersInput.Type;

export const UsersList = Schema.Struct({ "items": Schema.Array(AdminUser), "nextCursor": Schema.Union(Schema.String, Schema.Null) });

export type UsersList = typeof UsersList.Type;

export const Versions = Schema.Struct({ "items": Schema.Array(FileVersion), "nextCursor": Schema.Union(Schema.String, Schema.Null) });

export type Versions = typeof Versions.Type;
